import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Validate a discount percent value.
 * @param {unknown} value
 * @returns {boolean}
 */
function isValidDiscountPercent(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

/**
 * Calculate due date based on payment terms.
 * @param {string} issueDate Date in YYYY-MM-DD format
 * @param {string} terms Payment terms: 'NET14', 'NET30', or 'EOM'
 * @returns {string | null} Due date in YYYY-MM-DD format, or null if terms are invalid
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  }
  if (terms === 'NET30') {
    return addDays(issueDate, 30);
  }
  if (terms === 'EOM') {
    const [year, month] = issueDate.split('-').map(Number);
    const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
    return `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
  }
  return null;
}

/**
 * Create a new invoice from a customer and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer exists
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and calculate due date based on terms
  const dueDate = calculateDueDate(issueDate, terms);
  if (dueDate === null) return fail('TERMS_INVALID');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and expand each line
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discountPercent: explicit value wins over tier discount
    const hasOwnDiscount = 'discountPercent' in line;
    const discountPercent = hasOwnDiscount ? line.discountPercent : TIER_DISCOUNTS[customer.tier] ?? 0;
    if (!isValidDiscountPercent(discountPercent)) return fail('DISCOUNT_INVALID');

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    customerName: customer.name,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

